const PEOPLE={self:{name:'你',title:'今天的主角',initial:'我'},wing:{name:'Wing',title:'執行長',image:'./assets/wing.png'},spencer:{name:'Spencer',title:'董事長',image:'./assets/spencer.png'},rick:{name:'Rick',title:'技術資深經理',image:'./assets/rick.png',portrait:true},kind:{name:'阿良（Kind）',title:'技術經理',image:'./assets/kind.png',portrait:true},hope:{name:'Hope',title:'HR長',image:'./assets/hope.png',portrait:true},erich:{name:'Erich',title:'法務長',image:'./assets/erich.png',portrait:true},jenjen:{name:'JenJen',title:'行政長',image:'./assets/jenjen.png',portrait:true},sonny:{name:'Sonny',title:'MIS',image:'./assets/sonny.png',portrait:true},'exit-team':{name:'Erich · JenJen · Sonny',title:'法務／行政／MIS',members:['erich','jenjen','sonny']}};
function careerTrack(){if(!/^e(?:8|9|10|11|12|13|14|15)-/.test(run?.seed||''))return'';const info=careerInfo(run),assistant=run.assignment==='assistant';return `<div class="career-track"><div class="career-current"><span>目前職級</span><b>${assistant?'待轉正':esc(info.label)}</b></div><ol aria-label="五階職涯">${CAREER_LEVELS.map((level,index)=>`<li class="${!assistant&&index===run.rank?'current':''}" ${!assistant&&index===run.rank?'aria-current="step"':''}><i aria-hidden="true"></i><span>${esc(level.label)}</span></li>`).join('')}</ol><p>${assistant?'先把實際工作做出成績，爭取回到正式職務，再往管理職前進。':esc(info.responsibility)}</p><button data-action="career-guide">看看職涯路線 ↗</button></div>`;}
function careerGuide(){if(!/^e(?:8|9|10|11|12|13|14|15)-/.test(run?.seed||''))return;const ladder=CAREER_LADDERS[run.actualRoleId];openDialog(`<h2 id="dialog-title">職稱變了，要扛的事也會變。</h2><p class="dialog-lead">專業職稱與管理職級分開看。「專案經理」或「產品經理」可以是普通專業員工，升上帶人、分配資源的職位後，才進入管理階梯。</p><ol class="career-guide-list">${CAREER_LEVELS.map((level,index)=>`<li class="${index===run.rank&&run.assignment!=='assistant'?'current':''}"><span>${esc(level.label)}</span><h3>${esc(ladder[index])}</h3><p>${esc(level.responsibility)}</p></li>`).join('')}</ol><p class="dialog-lead">助理先爭取轉正；空降主管從經理級開始，也能選擇卸下管理職。升遷評核可用工作成果或討好老闆爭取，還能先補強能力。每一階都有管理抉擇，職級也會影響薪資與日常負擔；結果和實際增減，仍然選完才揭曉。${/^e(?:9|10|11|12|13|14|15)-/.test(run.seed)?'升遷要先累積目前職級的工作經歷，高階還要等名額與高層點頭；剛換名片，不能馬上再換一張。':''}</p><p class="small-note">${/^e(?:10|11|12|13|14|15)-/.test(run.seed)?'工作證的「準備升遷」可主動談訓練與評核；還沒準備好時，不會反覆叫你去領同一份表格。':' '}可以在工作證選擇離職，再決定如何結算職涯，不必等到最後一天。未玩到的結局依然保密。</p>`);}
let run=null,unlocked=[],legacy=[],records={},achievements={},recentAchievements=null,achievementFilter='all',achievementToastTimer,screen='home',selectedRole='ai',candidate=null,rerolls=0,storageAvailable=true,toastTimer,audioContext,audioGain,soundOn=false,collectionFilter={role:'all',status:'all',query:'',limit:24};
try{const saved=JSON.parse(localStorage.getItem(STORE)||'null'),v2=JSON.parse(localStorage.getItem('hedo-life-v2')||'null'),v1=JSON.parse(localStorage.getItem('hedo-life-v1')||'null');if(validRun(saved?.run))run=saved.run;unlocked=[...new Set([...(Array.isArray(saved?.unlocked)?saved.unlocked:[]),...(Array.isArray(v2?.unlocked)?v2.unlocked:[])])].filter(id=>ENDINGS.some(e=>e.id===id));achievements=readAchievementRecords(saved?.achievements);records=saved?.records&&typeof saved.records==='object'&&!Array.isArray(saved.records)?saved.records:{};legacy=[...new Set([...(Array.isArray(saved?.legacy)?saved.legacy:[]),...(Array.isArray(v2?.legacy)?v2.legacy:[]),...(Array.isArray(v1?.unlocked)?v1.unlocked:[])])].filter(id=>LEGACY_ENDINGS.some(e=>e.id===id));}catch{storageAvailable=false;}
function save(){try{localStorage.setItem(STORE,JSON.stringify({run,unlocked,legacy,records,achievements}));}catch{if(storageAvailable)toast('這個瀏覽器無法存檔，本局仍可繼續。');storageAvailable=false;}$('#collection-count').textContent=`${unlocked.length} / ${ENDINGS.length}`;$('#achievement-count').textContent=`${Object.keys(achievements).length} / ${ACHIEVEMENTS.length}`;}
function readAchievementRecords(value,source='local'){
 const result={};if(!value||typeof value!=='object'||Array.isArray(value))return result;
 for(const item of ACHIEVEMENTS){if(!Object.hasOwn(value,item.id))continue;const row=value[item.id],time=typeof row==='object'&&row?Date.parse(row.unlockedAt):NaN;if(!Number.isFinite(time))continue;result[item.id]={unlockedAt:new Date(time).toISOString(),source:source==='imported'?'imported':['local','verified','imported'].includes(row.source)?row.source:source};}
 return result;
}
function mergeVerifiedAchievements(rows){
 if(!Array.isArray(rows))return false;let changed=false;
 for(const row of rows){if(!row||!Object.hasOwn(ACHIEVEMENT_MAP,row.id))continue;const time=Date.parse(row.unlockedAt);if(!Number.isFinite(time))continue;const unlockedAt=new Date(time).toISOString(),old=achievements[row.id];if(!old||old.source!=='verified'||old.unlockedAt!==unlockedAt){achievements[row.id]={unlockedAt,source:'verified'};changed=true;}}
 return changed;
}
function achievementProgressKey(){return run?`${run.runId||run.seed}:${run.actions.length}:${run.completed?'end':'play'}`:'';}
function syncAchievementProof(){if(!run?.runId||!deriveAchievements(run).length)return;void cloud.achievementProgress(run).then(data=>{if(mergeVerifiedAchievements(data?.achievements))save();}).catch(()=>{});}
function collectAchievements(notify=true){
 if(!run)return;const ids=deriveAchievements(run).filter(id=>!Object.hasOwn(achievements,id));if(!ids.length)return;
 const unlockedAt=new Date().toISOString();for(const id of ids)achievements[id]={unlockedAt,source:'local'};
 recentAchievements={key:achievementProgressKey(),ids};if(notify)showAchievementToast(ids);syncAchievementProof();
}
function showAchievementToast(ids){
 const first=ACHIEVEMENT_MAP[ids[0]],panel=$('#achievement-toast');if(!first||!panel)return;clearTimeout(achievementToastTimer);panel.innerHTML=`<img src="${first.image}" alt=""><div><span>成就解鎖${ids.length>1?` · 共 ${ids.length} 枚`:''}</span><b>${esc(first.title)}</b></div><button data-action="achievements">翻開成就簿 ↗</button>`;panel.classList.add('visible');achievementToastTimer=setTimeout(()=>panel.classList.remove('visible'),6500);
}
function recentAchievementHTML(){
 if(recentAchievements?.key!==achievementProgressKey())return'';
 return `<section class="result-achievements" aria-label="這次解鎖的成就"><span class="ledger-label">這次也解鎖了</span><div>${recentAchievements.ids.map(id=>{const item=ACHIEVEMENT_MAP[id];return `<button data-action="achievements" class="result-achievement"><img src="${item.image}" alt=""><span><small>成就解鎖</small><b>${esc(item.title)}</b></span><span aria-hidden="true">↗</span></button>`;}).join('')}</div></section>`;
}
function achievementBook(){
 openDialog(`<div class="achievement-heading"><div><span class="eyebrow">LITTLE VICTORIES, STRANGE MEMORIES.</span><h2 id="dialog-title">有些事，值得留一枚章。</h2></div><span class="achievement-total"><b>${Object.keys(achievements).length}</b> / ${ACHIEVEMENTS.length}</span></div><p class="dialog-lead">把上班途中那些特別的瞬間收好。還沒拿到的成就，名字、圖案和條件都先保密。</p><div class="achievement-progress" role="meter" aria-label="已解鎖成就" aria-valuemin="0" aria-valuemax="${ACHIEVEMENTS.length}" aria-valuenow="${Object.keys(achievements).length}"><span style="width:${Object.keys(achievements).length/ACHIEVEMENTS.length*100}%"></span></div><div class="achievement-filters" role="group" aria-label="成就收藏狀態">${[['all','全部'],['unlocked','已解鎖'],['locked','未解鎖']].map(([id,label])=>`<button data-achievement-filter="${id}" aria-pressed="${achievementFilter===id}" class="${achievementFilter===id?'selected':''}">${label}</button>`).join('')}</div><p class="achievement-storage-note">成就先保存在這個瀏覽器，連線後以可重播紀錄驗證並同步。舊圖鑑照常保留；匯入的成就不會算進全站紀錄。</p><div class="achievement-grid">${ACHIEVEMENTS.filter(item=>achievementFilter==='all'||(achievementFilter==='unlocked')===Object.hasOwn(achievements,item.id)).map((item,index)=>{
 const row=achievements[item.id],number=String(ACHIEVEMENTS.indexOf(item)+1).padStart(2,'0');
 return row?`<article class="achievement-card unlocked"><div class="achievement-art"><img src="${item.image}" alt="${esc(item.title)}原創成就插畫" loading="lazy"><span class="achievement-check" aria-hidden="true">✓</span></div><div class="achievement-card-copy"><span class="achievement-category">${ACHIEVEMENT_GROUPS[item.group]} · ${number}</span><h3>${esc(item.title)}</h3><p>${esc(item.description)}</p><footer><time datetime="${esc(row.unlockedAt)}">${new Date(row.unlockedAt).toLocaleDateString('zh-TW')}</time><span>${row.source==='verified'?'已驗證同步':row.source==='imported'?'匯入收藏':'本機收藏'}</span></footer></div></article>`:`<article class="achievement-card locked" aria-label="第 ${number} 枚成就，尚未解鎖"><div class="achievement-art"><span aria-hidden="true">?</span></div><div class="achievement-card-copy"><span class="achievement-category">${number} / UNKNOWN</span><h3>???</h3><p>等那一天發生，再替它命名。</p></div></article>`;
 }).join('')||'<p class="empty-state">這裡還沒有收藏。先去過一天你的人生吧。</p>'}</div>`);
}
function rageControl(){if(!/^e(?:13|14|15)-/.test(run?.seed||''))return'';const available=canRequestRage(run),hint=run.pendingFamily?'這段離場選擇已經確定，先把最後一幕看完。':run.rageContext?'先看完這次暴走的後續。':!available&&getEvent(run)?.speaker==='self'?'眼前沒有人跟你說話，先把這個念頭放著。':!available?'今天已經出過這口氣，先繼續眼前的故事。':'';return `<button class="choice rage-trigger" data-action="rage" ${available?'':'disabled'} ${hint?`title="${hint}"`:''}><span class="rage-icon" aria-hidden="true">✹</span><span class="choice-text">受不了了，扁他</span><span class="choice-arrow" aria-hidden="true">↗</span></button>`;}
