function home(focus=true){view(`<section class="home"><div class="hero"><div class="hero-copy"><span class="eyebrow pill">OFFICE LIFE, UNPREDICTABLE.</span><h1>你的前途，<br><span>隨機應變。</span></h1><p class="hero-desc">履歷靠骰子，未來靠選擇。<br>歡迎加入移動。這一次，你能待到哪一天？</p><div class="hero-actions"><button class="primary" data-action="new">擲出我的人生 <span>↗</span></button><button class="text-button" data-action="${run?'continue':'about'}">${run?(run.completed?'回看上次人生':'繼續上班'):'入職前先看看'} <span>→</span></button></div><div class="hero-numbers"><div><b>09</b><span>應徵職缺</span></div><div><b>${ENDINGS.length}</b><span>未知結局</span></div><div><b>∞</b><span>意料之外</span></div></div></div><div class="hero-stage" aria-label="Wing 與董事長 Spencer 的遊戲角色"><span class="shape circle"></span><span class="shape ring"></span><span class="shape yellow"></span><div class="hero-person spencer"><img src="./assets/spencer.png" alt="Spencer 董事長卡通人物"><span>SPENCER <small>董事長</small></span></div><div class="hero-person wing"><img src="./assets/wing.png" alt="Wing 執行長卡通人物"><span>WING <small>執行長</small></span></div><div class="speech-bubble">「我們很重視人才。」<small>至於你算不算，明天再說。</small></div><div class="floating-dice" aria-hidden="true">⚄</div><span class="stage-note">FICTIONAL OFFICE UNIVERSE / V.03</span></div></div><div class="feature-strip"><div><span>01 / ROLL</span><h2>先骰履歷，再談理想。</h2><p>骰出能力、學歷和薪水，再決定怎麼過這段日子。</p></div><div><span>02 / CHOOSE</span><h2>選項沒有標準答案。</h2><p>同一句話，今天說沒事，明天說可能就被約談。</p></div><div><span>03 / DISCOVER</span><h2>下班的方式，玩過才知道。</h2><p>還沒玩到的結局先保密，問號等你自己打開。</p></div></div><div class="community-banner"><div><span class="eyebrow">THE STORY IS STILL BEING WRITTEN.</span><h2>還有哪個梗，老同事一定記得？</h2><p>把漏掉的梗、記憶與遊戲建議，交給「史冊補完計畫」。</p></div><button class="secondary" data-action="feedback">我來補一頁 <span>↗</span></button></div></section>`,'home',focus);}
function roleScreen(focus=true){view(`<section class="page roles-page"><div class="page-heading"><span class="eyebrow">STEP 01 / THE POSITION</span><h1>這次，你想應徵什麼？</h1><p class="page-lead">先選想做的工作。至於報到後做什麼，公司還有自己的想法。</p></div><div class="role-grid">${ROLES.map(r=>`<button class="role-card ${r.id===selectedRole?'selected':''}" data-role="${r.id}" aria-pressed="${r.id===selectedRole}"><span class="role-top"><span class="role-symbol">${r.symbol}</span><span class="check">${r.id===selectedRole?'✓':'↗'}</span></span><h2>${r.name}</h2><p class="role-subtitle">${esc(r.subtitle)}</p><p>${esc(r.description)}</p></button>`).join('')}</div><div class="role-bottom"><p>已選擇 <b>${ROLE_MAP[selectedRole].name}</b><small>職缺說明是一種美好的想像。</small></p><button class="primary" data-action="roll">擲出我的履歷 <span>⚄</span></button></div></section>`,'roles',focus);}
function rollCandidate(fresh=false){if(fresh)rerolls=0;else rerolls++;candidate=createRun(selectedRole,randomSeed());rollScreen();}
function rollScreen(){const dice=['⚀','⚁','⚂','⚃','⚄','⚅'];view(`<section class="page roll-page"><div class="page-heading"><span class="eyebrow">STEP 02 / A LITTLE LUCK</span><h1>這張履歷，夠有前途吧？</h1><p class="page-lead">能力、學歷和薪水都骰好了。報到後會不會照談好的走，再說。</p></div><div class="resume-card"><div class="resume-heading"><div><span class="eyebrow">CANDIDATE / ${ROLE_MAP[selectedRole].name}</span><h2>你的平行人生履歷</h2></div><span class="resume-stamp">READY<br>TO WORK</span></div><div class="dice-stats">${['skill','slack','lick'].map(k=>`<div class="dice-stat"><span>${STAT_LABELS[k]}</span><div class="dice-row" aria-label="骰子點數 ${(candidate.abilityDice?.[k]||[]).join('、')}">${(candidate.abilityDice?.[k]||[3,3,3]).map(d=>`<i>${dice[d-1]}</i>`).join('')}</div><b>${candidate.stats[k]}<small>/ 100</small></b></div>`).join('')}</div><div class="resume-details"><div><span>🎓 抽中的學歷</span><h3>${schoolHTML(candidate)}</h3></div><div><span>✦ 面試談好的月薪</span><h3 class="offer-salary">${candidate.offerPay||candidate.pay}<small>K / 月</small></h3></div></div><p class="resume-fine">學歷與薪資皆為遊戲隨機設定，並非你的真實資料。能力可以在故事裡成長。</p></div><div class="roll-actions"><button class="text-button" data-action="back-roles">← 換個職缺</button><button class="secondary" data-action="reroll" ${rerolls>=3?'disabled':''}>${rerolls>=3?'骰子今天下班了':`再擲一次 · 還有 ${3-rerolls} 次`} <span>↻</span></button><button class="primary" data-action="start">就這樣，報到吧 <span>↗</span></button></div></section>`,'roll');}
function stat(key,value){const danger=['boss','mood','energy','cash'].includes(key)&&value<=20;return `<div class="stat ${danger?'danger':''}"><div class="stat-top"><span>${STAT_LABELS[key]}</span><b>${value}</b></div><div class="stat-track" role="meter" aria-label="${STAT_LABELS[key]}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${value}"><div class="stat-fill" style="width:${value}%"></div></div></div>`;}
const signed=n=>`${n>0?'+':''}${n}`;
const LUCK_LABELS={success:'⚄ 這次順利過關',setback:'⚄ 這次不太順',lucky:'⚄ 這次運氣站在你這邊',ordinary:'⚄ 行動判定：平常發揮'};
function deltaChips(delta={}){return Object.entries(STAT_LABELS).filter(([k])=>Number.isFinite(delta[k])&&delta[k]!==0).map(([k,label])=>`<span class="delta-chip ${delta[k]>0?'delta-up':'delta-down'}"><span>${label}</span><b>${signed(delta[k])}</b></span>`).join('');}
function outcomeHTML(h,compact=false){const chips=deltaChips(h.delta);return `<div class="outcome-ledger ${compact?'compact':''}">${h.eventOutcome?`<p class="luck-result">⚄ ${esc(h.eventOutcome.label)}：${esc(h.eventOutcome.result)}</p>`:''}${h.chanceOutcome?`<p class="luck-result">${LUCK_LABELS[h.chanceOutcome]||'⚄ 命運已揭曉'}</p>`:''}<span class="ledger-label">這次實際變化</span><div class="delta-list" aria-label="事件後數值變化">${chips||'<span class="delta-neutral">數值沒有改變。</span>'}</div>${h.breakdown?.length?`<details class="effect-details"><summary>看看變化從哪裡來</summary><ul>${h.breakdown.map(part=>`<li><span>${esc(part.label)}</span><div class="delta-list">${deltaChips(part.delta)||'<span class="delta-neutral">已達數值上下限，沒有額外變化。</span>'}</div></li>`).join('')}</ul><p>上方是整件事的合計；數值介於 0～100，達到上限或下限後不再增減。</p></details>`:''}</div>`;}
// Outcome labels belong to an already committed history entry. Never infer the
