function rageReality(history){if(history?.eventId!=='rage-release')return null;const result=history.eventOutcome?.result;return result==='腦內劇場'?'imagined':result==='真的失控了'?'real':null;}
function displayHistoryResult(history){return rageReality(history)?polishDreamText(history.result):history.result;}
function realityHTML(history,compact=false){const reality=rageReality(history);if(!reality)return'';const imagined=reality==='imagined';return `<div class="reality-indicator reality-${reality} ${compact?'compact':''}"><span class="reality-symbol" aria-hidden="true">${imagined?'☾':'!'}</span><div><b>${imagined?'腦內夢境':'現實失控'}</b><span>${imagined?'現實沒有動手':'事情真的發生了'}</span></div>${imagined?'<span class="dream-sleep" aria-hidden="true">z z Z</span>':''}</div>`;}
function sourceLine(ids){const src=(ids||[]).map(id=>SOURCES[id]).filter(Boolean);return src.length?src.map(s=>s.url?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a>`:esc(s.title)).join(' · '):'原創職場平行宇宙';}
function speakerFor(event){if(event.speaker&&PEOPLE[event.speaker])return event.speaker;return 'wing';}
function visibleChoices(){return getEvent(run).choices.map((c,i)=>({c,i})).filter(({c})=>c.available!==false);}
function careerControl(){if(!/^e(?:10|11|12|13|14|15)-/.test(run.seed)||run.rank>=4)return '';const available=canRequestCareer(run),hint=run.turn>=20?'本局的升遷評核已結束，先完成接下來的故事。':run.pip?.active?'先完成目前的PIP，再考慮下一份名片。':run.turn<3?'先完成幾天工作，再來整理升遷準備。':available?'整理升遷準備，或用目前的成果爭取下一階。':'先完成目前通知；上次評核後需隔幾個工作日，婉拒後會再多留一點時間。';return `<button data-action="career" ${available?'':'disabled'} title="${hint}">準備升遷 ↗</button>`;}
function mobileWorkbar(){return `<div class="mobile-workbar"><button data-action="work-card">工作證與數值 ↑</button><span>心情 ${run.stats.mood} · 體力 ${run.stats.energy} · 存款 ${run.stats.cash}${run.pip?.active?` · PIP 剩 ${run.pip.remaining} 回合`:''}</span></div>`;}
function game(focus=true){if(!run)return roleScreen();if(run.completed)return endingScreen();const current=getEvent(run),last=run.history.at(-1),ev=run.pending&&last?.eventId===current.id?{...current,title:last.title,body:last.body}:current,crisis=ev.kind==='crisis',person=speakerFor(ev),p=PEOPLE[person],choices=visibleChoices(),reality=run.pending?rageReality(last):null;view(`<section class="game-layout"><aside class="game-sidebar" tabindex="-1"><div class="player-card"><div class="employee-line"><span class="eyebrow">MY WORK ID</span><span class="level">LV.${run.rank}</span></div><h2>${esc(jobTitle(run))}</h2><p class="job-origin">應徵：${ROLE_MAP[run.roleId].name}${run.assignment!=='honest'?` <span class="job-warning">${run.assignment==='assistant'?'實際職務':'職務異動'}</span>`:''}</p>${careerTrack()}<div class="salary-line"><span>遊戲月薪</span><b>${run.pay}<small>K</small></b></div><div class="education-mini">${schoolHTML(run)}</div></div><div class="boss-panel ${run.stats.boss<=20?'angry':''}"><div class="boss-intro">${avatar('wing')}<div><b>Wing</b><small>${bossLabel(run.stats.boss)}</small></div><span class="mood-dot"></span></div><div class="mood-stats">${stat('boss',run.stats.boss)}${stat('mood',run.stats.mood)}</div></div><div class="resource-stats">${['energy','cash','trust','dream'].map(k=>stat(k,run.stats[k])).join('')}</div><div class="skill-stats">${['skill','slack','lick'].map(k=>stat(k,run.stats[k])).join('')}</div>${run.pip?.active?`<div class="pip-status"><span>Hope 的改善計畫</span><b>剩 ${run.pip.remaining} 回合</b></div>`:''}<div class="sidebar-controls"><button data-action="guide">數值與運氣怎麼算？ ↗</button>${/^e(?:[2-9]|10|11|12|13|14|15)-/.test(run.seed)?`<button data-action="break" ${canRequestBreak(run)?'':'disabled'} title="一般工作事件中，每個工作回合可紓壓一次。先看完目前結果或通知。">花錢喘口氣 ↗</button>`:''}${careerControl()}<button data-action="journal">背鍋紀錄 ↗</button><button class="mobile-return-story" data-action="story">回到故事 ↓</button><button data-action="exit" ${run.pending||['rage','rage-world','self-care'].includes(ev.kind)||['exit-menu','career-exit','rank-exit','story-exit','career-step-down'].includes(ev.id)?'disabled':''}>我想離職了 ↗</button></div></aside><article class="chapter ${crisis?'crisis-chapter':''}" tabindex="-1">${mobileWorkbar()}${!/^e(?:[2-9]|10|11|12|13|14|15)-/.test(run.seed)?'<div class="rules-notice"><p>這局保留原本的玩法。新版心情消耗、花錢紓壓與更多史冊事件，從新人生開始。</p><button class="text-button" data-action="new">開一段新人生 ↗</button></div>':''}<div class="chapter-meta"><span>${crisis?'SOMETHING HAPPENED':`DAY ${pad(Math.min(run.turn+1,MAX_TURNS))} / ${esc(ev.era||'上班日常')}`}</span><span class="tag">${reality==='imagined'?'腦內夢境':ev.kind==='rage-world'?'失控後的世界':ev.kind==='rage'?(/^e(?:14|15)-/.test(run.seed)?'當場暴走':'卡通暴走'):ev.kind==='banquet'?'尾牙之夜':ev.id==='kind-workday'?'突然被揪':ev.kind==='self-care'?'喘口氣':ev.kind==='onboarding'?'報到日':ev.kind==='fantasy'?'平行未來':ev.kind==='career'&&/^e(?:8|9|10|11|12|13|14|15)-/.test(run.seed)?'職涯選擇':crisis?'臨時通知':'移動日常'}</span></div><div class="chapter-progress"><span style="width:${Math.min(100,(run.turn+1)/MAX_TURNS*100)}%"></span></div><h1 class="chapter-title">${esc(ev.title)}</h1><p class="chapter-body">${esc(ev.body)}</p>${ev.wing?`<div class="character-quote">${avatar(person,'quote-avatar')}<div><span class="speaker-name">${p.name} <small>${p.title} · 遊戲角色</small></span><p>${esc(ev.wing)}</p></div></div>`:''}${run.pending?`<div class="consequence${reality?` ${reality}-consequence`:``}" role="status"${reality?` aria-label="${reality==='imagined'?'腦內夢境結果':'現實失控結果'}"`:``}>${realityHTML(last)}<span class="eyebrow">AND THEN… / 結果是這樣的</span><p class="result-text">${esc(displayHistoryResult(last))}</p>${last.weather?`<p class="weather-note">☁ ${esc(last.weather.text)}</p>`:''}${outcomeHTML(last)}${recentAchievementHTML()}${reality==='imagined'?'<p class="dream-return-note"><b>睜開眼，還在原地。</b>剛才只發生在你的腦海，接著繼續面對眼前的事。</p>':''}<div class="result-footer"><span>${reality==='imagined'?'夢醒了，故事繼續。':'故事已記入這次人生'}</span><button class="primary" data-action="next">${reality==='imagined'?'回到現實':reality==='real'?'面對後續':'繼續'} <span>→</span></button></div></div><div class="rage-result-action">${rageControl()}</div>`:`<div class="choices-label"><span>如果是你，會怎麼做？</span><small>想怎麼回，就怎麼回。</small></div><div class="choices ${ev.kind==='rage'?'rage-choices':''}">${choices.map(({c,i},n)=>`<button class="choice ${c.rageTarget?'rage-target-choice':''}" data-choice="${i}">${c.rageTarget?avatar(c.rageTarget,'rage-choice-avatar'):''}<span class="choice-key">${pad(n+1)}</span><span class="choice-text">${esc(c.text)}</span><span class="choice-arrow">↗</span></button>`).join('')}${rageControl()}</div>`}${!/^e(?:14|15)-/.test(run.seed)?'<p class="upgrade-inline">新的當場暴走與失控後續，從新人生開始。這局保留原本規則，符合條件的成就仍能補收。</p>':''}<p class="story-source">創作靈感 / ${sourceLine(ev.sourceIds)}</p></article></section>`,'game',focus);if(focus){if(window.matchMedia('(max-width:800px)').matches){const target=run.pending?$('.consequence'):$('.chapter');target.scrollIntoView({block:'start',behavior:'instant'});if(!run.pending)target.focus({preventScroll:true});}else if(run.pending)$('.consequence').scrollIntoView({block:'nearest',behavior:'instant'});}}
const types={good:'GOOD END',bad:'BAD END',normal:'ANOTHER LIFE',secret:'HIDDEN CHAPTER'};
function finishRecord(){collectAchievements();if(run?.completed){if(!unlocked.includes(run.endingId)){unlocked.push(run.endingId);records[run.endingId]={turn:run.turn+1,job:jobTitle(run),pay:run.pay};toast(`一個問號，有了答案。${unlocked.length} / ${ENDINGS.length}`);}void cloud.complete(run);}save();}
function endingScreen(){const e=ENDINGS.find(e=>e.id===run?.endingId);if(!e)return home();view(`<section class="ending-page"><div class="ending-paper ${e.type==='bad'?'bad-ending':''}"><div class="ending-top"><span>THE MOVING LIFE / ${String(ENDINGS.indexOf(e)+1).padStart(3,'0')}</span><span>已解鎖 ✓</span></div><div class="ending-layout"><div><span class="ending-type">${types[e.type]}</span><h1>${esc(e.title)}</h1><p class="ending-subtitle">${esc(e.subtitle)}</p><p class="ending-body">${esc(e.body)}</p></div><div class="ending-symbol" aria-hidden="true"><span>${esc(e.symbol||'終')}</span><small>YOUR STORY.<br>YOUR ENDING.</small></div></div><div class="ending-employment"><span>應徵 <b>${ROLE_MAP[run.roleId].name}</b></span><span>實際 <b>${esc(jobTitle(run))}</b></span><span>存活 <b>${Math.min(run.turn+1,MAX_TURNS)} 回合</b></span><span>遊戲月薪 <b>${run.pay}K</b></span></div><div class="ending-stats">${Object.entries(STAT_LABELS).map(([k,v])=>`<div><b>${run.stats[k]}</b><span>${v}</span></div>`).join('')}</div></div>${recentAchievementHTML()}<div class="ending-actions"><button class="primary" data-action="new">再活一次 <span>↻</span></button><button class="secondary" data-action="collection">翻開命運圖鑑 <span>↗</span></button><button class="text-button" data-action="download">下載離場證明 ↓</button></div><button class="text-button ending-achievements-link" data-action="achievements">翻開成就簿 · ${Object.keys(achievements).length} / ${ACHIEVEMENTS.length} ↗</button><p class="ending-note">每一種離開，都不必等到最後。你的下一次人生，還有 ${ENDINGS.length-unlocked.length} 個問號。</p><details class="review-run"><summary>回看這次人生的背鍋紀錄</summary>${journalHTML()}</details></section>`,'ending');}
function openDialog(html){$('#dialog-content').innerHTML=html;if(!dialog.open)dialog.showModal();dialog.scrollTop=0;}
function collection(){collectionFilter={role:'all',status:'all',query:'',limit:24};openDialog(`<h2 id="dialog-title">還沒遇見的，都先保密。</h2><p class="dialog-lead">${unlocked.length} / ${ENDINGS.length} 個問號已有答案。剩下的，留給下一次選擇。</p><div class="collection-controls"><label for="filter-role">應徵職業<select id="filter-role"><option value="all">全部職業</option>${ROLES.map(r=>`<option value="${r.id}">${r.name}</option>`).join('')}</select></label><label for="filter-status">收藏狀態<select id="filter-status"><option value="all">全部</option><option value="unlocked">已收藏</option><option value="locked">未解鎖</option></select></label><label for="filter-query">搜尋已收藏的故事<input id="filter-query" type="search" placeholder="只搜尋你已解鎖的結局"></label></div><p id="collection-summary" class="collection-summary"></p><div class="collection-grid" id="ending-grid"></div><button class="load-more secondary" data-action="more-endings">再翻一頁 ↓</button>${legacy.length?`<details class="review-run"><summary>第一版收藏（${legacy.length}）</summary><div class="collection-grid">${LEGACY_ENDINGS.filter(e=>legacy.includes(e.id)).map(e=>`<article class="ending-card unlocked"><span class="number">FIRST EDITION</span><h3>${esc(e.title)}</h3><p>${esc(e.body)}</p></article>`).join('')}</div></details>`:''}`);renderCollection();}
function renderCollection(){const f=collectionFilter,list=ENDINGS.filter(e=>(f.role==='all'||e.roleId===f.role)&&(f.status==='all'||(f.status==='unlocked')===unlocked.includes(e.id))&&(!f.query||(unlocked.includes(e.id)&&[e.title,e.body,e.subtitle].join(' ').toLowerCase().includes(f.query.toLowerCase()))));$('#collection-summary').textContent=`${list.length} 張卡片 · 顯示 ${Math.min(f.limit,list.length)} 張`;$('#ending-grid').innerHTML=list.slice(0,f.limit).map(e=>{const yes=unlocked.includes(e.id);return yes?`<article class="ending-card unlocked"><div class="card-top"><span class="number">${String(ENDINGS.indexOf(e)+1).padStart(3,'0')} / ${ROLE_MAP[e.roleId].name}</span><span>✓</span></div><h3>${esc(e.title)}</h3><p>${esc(e.body)}</p></article>`:`<article class="ending-card locked" aria-label="未解鎖結局"><span class="unknown-number">${String(ENDINGS.indexOf(e)+1).padStart(3,'0')}</span><span class="question-mark" aria-hidden="true">?</span><p>未完待續</p></article>`;}).join('')||'<p class="empty-state">已收藏的故事裡找不到這個關鍵字。</p>';$('.load-more').hidden=f.limit>=list.length;}
function journalHTML(){if(!run?.history.length)return'<p class="dialog-lead">還沒開始背鍋，這裡暫時空白。</p>';return`<ol class="journal-list">${run.history.map((h,i)=>`<li><span class="eyebrow">${pad(i+1)} / DAY ${h.turn+1}</span><h3>${esc(h.title)}</h3>${realityHTML(h,true)}<p class="journal-choice">${esc(h.choiceText)}</p><p>${esc(displayHistoryResult(h))}</p>${h.weather?`<p class="weather-note">☁ ${esc(h.weather.text)}</p>`:''}${outcomeHTML(h,true)}<small>${esc(h.jobTitle)} · 遊戲月薪 ${h.pay}K</small></li>`).join('')}</ol>`;}
function about(){openDialog(`<h2 id="dialog-title">報到前，先看這幾件事。</h2><p class="dialog-lead">先選職缺，再骰履歷。工作、偷懶、舔功各有用途；有些事看能力，有些事真的要看運氣。</p><div class="rule-grid"><div><span>01</span><h3>先選擇，再揭曉</h3><p>相似的選擇也可能遇到不同結果。選完才會顯示實際數值增減與這次的運氣。</p></div><div><span>02</span><h3>上班會消耗心情</h3><p>心情會隨上班消耗，老闆也有自己的脾氣。撐不住時，可以花存款休息一下。</p></div><div><span>03</span><h3>隨時可以離開</h3><p>工作證上有離職按鈕。想走的時候，就有離開的路線。</p></div><div><span>04</span><h3>問號留給自己解開</h3><p>最多24個工作回合。每一步自動存檔，解鎖的故事收進命運圖鑑，特別的瞬間留在成就簿。</p></div></div><p class="dialog-lead">學歷、薪水與人物偏見均是虛構遊戲設定；不同學校與科系不代表能力高低。老闆的偏見，是他的問題。</p>`);}
function statGuide(){openDialog(`<h2 id="dialog-title">能力有什麼用？哪些事看運氣？</h2><p class="dialog-lead">選擇前不揭曉數值與判定。選擇後可看實際增減、運氣結果與變化明細；背鍋紀錄也會保留。</p><div class="guide-table"><table><caption>每個數值都有用途</caption><thead><tr><th scope="col">數值</th><th scope="col">會影響什麼</th></tr></thead><tbody><tr><th scope="row">老闆心情</th><td>人事危機、協商與升遷的判定，也會受當天隨機脾氣影響。PIP 不會自動讓他開心。</td></tr><tr><th scope="row">自己心情</th><td>每次工作會消耗，低落時出現情緒危機。PIP、低體力與砍薪後的壓力會讓上班更難熬。</td></tr><tr><th scope="row">體力</th><td>做事與救火的本錢，耗盡會結束這段人生，也關係到後期能否走下去。</td></tr><tr><th scope="row">存款</th><td>0～100 的遊戲資源點數，並非新臺幣。可以花來紓壓，耗盡也會離場；遊戲月薪決定定期入帳多少。</td></tr><tr><th scope="row">同事情義</th><td>與同事合作、互助會累積，部分後期路線需要這份交情。</td></tr><tr><th scope="row">大餅信仰</th><td>你對公司願景還抱著多少期待，會影響部分後期路線。</td></tr><tr><th scope="row">工作能力</th><td>協商、PIP 答辯、升遷及做事遇到好結果的機會；新版管理職還會看帶人與合作的累積，能力高也不保證成功。</td></tr><tr><th scope="row">偷懶能力</th><td>提高省電時遇到好運的機會，降低一般工作事件的倒楣機會，並影響職涯選擇。</td></tr><tr><th scope="row">舔老闆能力</th><td>討好型協商、升遷與相關選擇的成功機會，也影響職涯選擇。</td></tr></tbody></table></div><div class="rule-grid"><div><span>⚄ / 入職</span><h3>每一局，重新發牌</h3><p>能力、學歷、科系和薪水都用骰的。職務也可能被改派，空降主管則直接迎接原職挑戰。</p></div><div><span>⚄ / 工作</span><h3>同樣的選擇，也有變數</h3><p>日常事件會抽取；選擇後會判定幸運、平常或不順，並抽出老闆當天的脾氣。部分事件另有劇情抽籤，結果會在事後顯示。</p></div><div><span>⚄ / 人事</span><h3>能力影響機會</h3><p>協商、PIP 答辯及升遷會判定成敗；學歷閒聊、砍薪時機與幅度也會隨機變動。</p></div><div><span>☕ / 紓壓</span><h3>薪水也可以花在自己身上</h3><p>一般工作事件中，每回合可花錢喘口氣一次。餐點、朋友與休息的療癒效果也有高低。阿良也可能在上班途中突然過來揪團，跟不跟由你決定；錢不足時不會提供買不起的選項。</p></div></div><p class="small-note">新人生可在一般選項下方按「受不了了，扁他」，直接回應眼前跟你說話的人。心情、對象和時機都會影響後續，按下後才揭曉發生了什麼事。尾牙也會在上班途中隨機登場。舊局保留原規則，可開新人生體驗。</p>${run&&!/^e(?:[2-9]|10|11|12|13|14|15)-/.test(run.seed)?'<p class="small-note">你目前這局沿用舊版規則，以保留進度。新的心情消耗、PIP 調整與紓壓功能會從新局開始。</p>':''}`);}
function sources(){openDialog(`<h2 id="dialog-title">這些故事，從哪裡來？</h2><p class="dialog-lead">本作是非官方職場諷刺遊戲。參考私人史冊的敘事與公開產品資料；角色台詞、因果、薪資與結局皆為創作，不是企業現況報告。</p><div class="sources-list">${Object.values(SOURCES).map((s,i)=>`<article class="source-item"><span class="number">${pad(i+1)}</span><div><h3>${s.url?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a>`:esc(s.title)}</h3><p>${esc(s.summary||'私人史冊虛構敘事改編。')}</p></div></article>`).join('')}</div><p class="source-disclaimer">互動節奏參考 <a href="https://otherlife.icareu.tw/" target="_blank" rel="noopener noreferrer">地球轉生所</a> 與 <a href="https://1in8b.life/zh/" target="_blank" rel="noopener noreferrer">八十億分之一</a>；視覺色彩參考 <a href="https://www.avividai.com/" target="_blank" rel="noopener noreferrer">AviviD 官網</a>。未使用官方標誌或暗示官方製作。</p>`);}
function feedback(){feedbackUI.open();}
function privacy(){const state=cloud.state;openDialog(`<h2 id="dialog-title">你的收藏怎麼保存？</h2><p class="dialog-lead">不用註冊。這個瀏覽器會產生隨機匿名識別碼，讓你保留自己的結局與成就收藏。</p><div class="privacy-card"><h3>${state.playerId?`匿名玩家 ${esc(state.playerId.slice(0,8))}`:'本機收藏模式'}</h3><p>目前：${state.status==='online'?'已連接人生觀測站':state.status==='pending'?'等待同步':'收藏仍保存在這個瀏覽器'}</p>${state.lastError?`<p class="sync-notice">${esc(state.lastError)}</p>`:''}<p>遊戲紀錄保存匿名玩家、已驗證結局、遊戲職業、回合數、遊戲薪資與完成時間。成就不必等到結局就能同步，另存成就編號與首次解鎖時間。驗證時暫時重播遊戲紀錄，並以種子的雜湊綁定本局編號；伺服器不保存原始選擇、種子或劇情。不要求姓名、Email、真實學歷，也不保存原始 IP。</p><p>只有你主動參與「史冊補完計畫」時，才會把填寫的文字送到私人投稿佇列，並建立公開的 GitHub Issue。佇列保存匿名玩家 ID、投稿編號、原文與處理狀態；成功開單後立即刪除站內原文，未成功的原文最多保留 30 天。公開 Issue 不含匿名玩家 ID 或遊戲紀錄。</p><p>投稿防濫用另保存短期連線雜湊，3 天內清理；不保存原始 IP。GitHub 上已公開的投稿仍會保留。</p><p>統計頁只顯示總數。清除瀏覽器資料後，無法靠姓名找回這個匿名身分；不同裝置會是不同玩家。</p><div class="privacy-actions"><button class="secondary" data-action="sync">重新連線 ↻</button><button class="text-button" data-action="export-collection">匯出圖鑑 ↓</button><label class="text-button import-label">匯入圖鑑 ↑<input id="import-collection" type="file" accept="application/json,.json" hidden></label></div><p>匯出檔案包含故事與成就收藏，不含匿名登入憑證。跨網址或裝置可用匯出／匯入帶走收藏；匯入只加入本機，不增加全站統計，也不會自動標成已驗證。</p></div>`);}
function careerStatsHTML(data){const counts=CAREER_LEVELS.map((level,index)=>({...level,count:ENDINGS.filter(ending=>ending.family===CAREER_FAMILIES[index]).reduce((total,ending)=>total+Math.max(0,Number(data.endings?.find(row=>row.id===ending.id)?.count)||0),0)})),max=Math.max(1,...counts.map(row=>row.count)),total=counts.reduce((sum,row)=>sum+row.count,0);return `<section class="chart-panel"><div class="chart-heading"><h3>大家把職涯停在哪一階？</h3><span>五階職涯結算 · ${total}局</span></div><div class="bar-chart" role="img" aria-label="${esc(counts.map(row=>`${row.label}：${row.count}局`).join('，'))}">${counts.map(row=>`<div class="bar-row"><span>${esc(row.label)}</span><div><i style="width:${row.count/max*100}%"></i></div><b>${row.count}</b></div>`).join('')}</div><p class="small-note">只計入選擇五階職涯結算的紀錄，其他離場路線不列入此圖。結局名稱依然保密。</p></section>`;}
async function statistics(){openDialog(`<h2 id="dialog-title">人生觀測站。</h2><p class="dialog-lead">看看大家玩過多少局、從哪些職缺出發。結局名稱依然保密。</p><div id="stats-content" aria-live="polite"><p class="empty-state">正在整理大家的人生…</p></div>`);try{const data=await cloud.stats();if(!$('#stats-content'))return;const roles=ROLES.map(r=>({...r,count:Number(data.roles?.find(x=>x.id===r.id)?.count)||0})),max=Math.max(1,...roles.map(r=>r.count)),total=Number(data.totalRuns)||0,days=data.daily||[],dayMax=Math.max(1,...days.map(d=>Number(d.count)||0));$('#stats-content').innerHTML=`<div class="stat-tiles"><div><b>${Number(data.players)||0}</b><span>匿名玩家</span></div><div><b>${total}</b><span>已完成的人生</span></div><div><b>${Number(data.uniqueEndings)||0}<small> / ${ENDINGS.length}</small></b><span>大家遇見的結局</span></div><div><b>${Number(data.averageTurns||0).toFixed(1)}</b><span>平均存活回合</span></div></div>${!total?'<p class="empty-state">還沒有人完成這段人生。第一份離場證明，等你寫下。</p>':''}<section class="chart-panel"><div class="chart-heading"><h3>大家從什麼職缺出發？</h3><span>已完成局數</span></div><div class="bar-chart" role="img" aria-label="${esc(roles.map(r=>`${r.name}：${r.count}局`).join('，'))}">${roles.map(r=>`<div class="bar-row"><span>${r.name}</span><div><i style="width:${r.count/max*100}%"></i></div><b>${r.count}</b></div>`).join('')}</div></section>${careerStatsHTML(data)}<section class="chart-panel"><div class="chart-heading"><h3>最近的人生動態</h3><span>每日完成局數 · UTC</span></div>${days.length?`<div class="daily-chart" role="img" aria-label="${esc(days.slice(-14).map(d=>`${d.date}：${d.count}局`).join('，'))}">${days.slice(-14).map(d=>`<div title="${esc(d.date)}：${Number(d.count)}局"><b>${Number(d.count)}</b><span style="height:${Math.max(3,Number(d.count)/dayMax*110)}px"></span><small>${esc(d.date.slice(5))}</small></div>`).join('')}</div>`:'<p class="empty-state">還沒有每日遊玩紀錄。</p>'}</section><p class="small-note">匿名遊玩統計，不是員工或企業現況調查。未解鎖的結局名稱，在這裡也不會出現。</p>`;}catch{if($('#stats-content'))$('#stats-content').innerHTML='<div class="empty-state"><h3>觀測站暫時休息。</h3><p>遊戲和本機圖鑑照常運作；連線恢復後會再同步。</p><button class="secondary" data-action="stats">重新整理 ↻</button></div>';}}
function downloadCard(){const e=ENDINGS.find(e=>e.id===run.endingId),lines=[],body=Array.from(e.body);while(body.length)lines.push(body.splice(0,23).join(''));const statBase=Math.max(810,320+lines.length*35+70),height=statBase+350;const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="900" height="${height}" viewBox="0 0 900 ${height}"><rect width="900" height="${height}" fill="#fff7fa"/><circle cx="820" cy="80" r="180" fill="#fbdce8"/><rect x="35" y="35" width="830" height="${height-70}" rx="28" fill="none" stroke="#e6256e" stroke-width="2"/><g fill="#14192d" font-family="sans-serif"><text x="80" y="110" font-size="20" letter-spacing="3">THE MOVING LIFE / 移動人生</text><text x="80" y="170" font-size="18" fill="#e6256e">${esc(types[e.type])}</text><text x="80" y="250" font-size="48" font-weight="700">${esc(e.title)}</text>${lines.map((l,i)=>`<text x="80" y="${330+i*35}" font-size="25">${esc(l)}</text>`).join('')}<text x="80" y="${statBase-35}" font-size="18">應徵 ${ROLE_MAP[run.roleId].name} → 實際 ${esc(jobTitle(run))}</text><line x1="80" y1="${statBase}" x2="820" y2="${statBase}" stroke="#e9bed0"/>${Object.entries(STAT_LABELS).map(([k,v],i)=>`<text x="${85+(i%3)*250}" y="${statBase+48+Math.floor(i/3)*55}" font-size="21">${v}　${run.stats[k]}</text>`).join('')}<text x="80" y="${height-105}" font-size="18">第${Math.min(run.turn+1,MAX_TURNS)}回合離場 · 遊戲月薪${run.pay}K</text><text x="80" y="${height-65}" font-size="13">非官方職場諷刺遊戲 · 人物對白與結局為虛構改編</text></g></svg>`;const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`移動人生-${e.title}.svg`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('離場證明已下載。這份不用任何人簽名。');}
async function toggleSound(){try{if(!audioContext){audioContext=new(window.AudioContext||window.webkitAudioContext)();audioGain=audioContext.createGain();audioGain.gain.value=0;audioGain.connect(audioContext.destination);[130.81,196,261.63,329.63].forEach((freq,i)=>{const o=audioContext.createOscillator(),g=audioContext.createGain();o.type='sine';o.frequency.value=freq;g.gain.value=.12/(i+1);o.connect(g);g.connect(audioGain);o.start();});}await audioContext.resume();soundOn=!soundOn;audioGain.gain.setTargetAtTime(soundOn?.055:0,audioContext.currentTime,.3);$('.sound-button').setAttribute('aria-pressed',soundOn);$('.sound-button').setAttribute('aria-label',soundOn?'關閉背景音效':'開啟背景音效');$('#sound-label').textContent=soundOn?'聲音開':'聲音關';}catch{toast('目前無法播放音效。');}}
function choose(index){if(screen!=='game'||run.pending||dialog.open)return;const c=getEvent(run).choices[index];if(!c||c.available===false)return;run=applyChoice(run,index);collectAchievements();save();game();}
function next(){run=advance(run);finishRecord();game();}
function newLife(){if(run&&!run.completed)openDialog(`<h2 id="dialog-title">重新擲一段人生？</h2><p class="dialog-lead">目前在第 ${run.turn+1} 回合。開始新局會取代這局進度；已收藏的故事都會保留。</p><div class="ending-actions"><button class="primary" data-action="confirm-new">選新職缺 →</button><button class="text-button" data-action="close-dialog">先保留這一局</button></div>`);else roleScreen();}
function readFilter(){collectionFilter.role=$('#filter-role').value;collectionFilter.status=$('#filter-status').value;collectionFilter.query=$('#filter-query').value.trim();collectionFilter.limit=24;renderCollection();}
let searchTimer;document.addEventListener('input',event=>{if(event.target.id==='filter-query'){clearTimeout(searchTimer);searchTimer=setTimeout(readFilter,120);}});document.addEventListener('change',event=>{if(event.target.id?.startsWith('filter-'))readFilter();});
document.addEventListener('click',async event=>{const rb=event.target.closest('[data-role]');if(rb){selectedRole=rb.dataset.role;roleScreen(false);$(`[data-role="${selectedRole}"]`).focus({preventScroll:true});return;}const af=event.target.closest('[data-achievement-filter]');if(af){achievementFilter=af.dataset.achievementFilter;achievementBook();$(`[data-achievement-filter="${achievementFilter}"]`).focus({preventScroll:true});return;}const cb=event.target.closest('[data-choice]');if(cb){choose(Number(cb.dataset.choice));return;}const action=event.target.closest('[data-action]')?.dataset.action;if(!action)return;
 if(action==='home')home();if(action==='new')newLife();if(action==='confirm-new'){dialog.close();roleScreen();}if(action==='roll')rollCandidate(true);if(action==='reroll'&&rerolls<3)rollCandidate();if(action==='back-roles')roleScreen();if(action==='start'&&candidate){run=structuredClone(candidate);run.runId=crypto.randomUUID();candidate=null;save();game();}if(action==='continue')game();if(action==='next')next();if(action==='exit'){run=requestExit(run);save();game();}if(action==='collection')collection();if(action==='achievements')achievementBook();if(action==='rage'){const nextRun=requestRage(run);if(nextRun!==run){run=nextRun;finishRecord();game();}}if(action==='more-endings'){collectionFilter.limit+=24;renderCollection();}if(action==='sources')sources();if(action==='about')about();if(action==='guide')statGuide();if(action==='career-guide')careerGuide();if(action==='story'){const chapter=$('.chapter');chapter.scrollIntoView({block:'start',behavior:'instant'});chapter.focus({preventScroll:true});}if(action==='work-card'){const card=$('.game-sidebar');card.scrollIntoView({block:'start',behavior:'instant'});card.focus({preventScroll:true});}if(action==='career'){const nextRun=requestCareer(run);if(nextRun!==run){run=nextRun;save();game();}}if(action==='break'){const nextRun=requestBreak(run);if(nextRun!==run){run=nextRun;save();game();}}if(action==='feedback')feedback();if(action==='privacy')privacy();if(action==='stats')void statistics();if(action==='sync'){await syncCloud();toast(cloud.state.status==='online'?'已連接觀測站。':'目前仍是本機模式，收藏都還在。');privacy();}if(action==='journal')openDialog(`<h2 id="dialog-title">這次上班，發生過什麼事。</h2><p class="dialog-lead">選過的回覆、發生的結果和數值變化，都記在這裡。</p>${journalHTML()}`);if(action==='close-dialog')dialog.close();if(action==='download')downloadCard();if(action==='sound')toggleSound();if(action==='export-collection')exportCollection();});
document.addEventListener('keydown',event=>{if(event.altKey||event.ctrlKey||event.metaKey||event.repeat||dialog.open||['INPUT','SELECT','TEXTAREA'].includes(event.target.tagName))return;if(screen==='game'&&!run.pending&&/^[1-9]$/.test(event.key)){const picked=visibleChoices()[Number(event.key)-1];if(picked){event.preventDefault();choose(picked.i);}}});
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
let lastSyncNotice='';cloud.subscribe(s=>{if(mergeVerifiedAchievements(s.achievements))save();$('#cloud-status').textContent=s.status==='online'?'● 匿名紀錄已連線':s.status==='connecting'?'連接觀測站…':s.status==='pending'?`○ ${s.pending} 筆待同步`:'○ 本機收藏模式';$('#cloud-status').title=s.lastError||'';if(s.lastError&&s.lastError!==lastSyncNotice){lastSyncNotice=s.lastError;toast(s.lastError);}});
async function syncCloud(){const data=await cloud.init();if(mergeVerifiedAchievements(data?.achievements))save();if(run?.runId&&deriveAchievements(run).some(id=>achievements[id]?.source!=='verified'))syncAchievementProof();if(data&&run?.completed)void cloud.complete(run);if(data?.unlocked){unlocked=[...new Set([...unlocked,...data.unlocked.filter(id=>ENDINGS.some(e=>e.id===id))])];save();}}
function exportCollection(){const blob=new Blob([JSON.stringify({format:'hedo-collection',version:3,unlocked,legacy,achievements},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='移動人生-我的圖鑑.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('圖鑑已匯出，檔案不含匿名登入金鑰。');}
document.addEventListener('change',async event=>{if(event.target.id!=='import-collection')return;const file=event.target.files?.[0];if(!file)return;try{if(file.size>100000)throw new Error();const data=JSON.parse(await file.text());if(data.format!=='hedo-collection'||!Array.isArray(data.unlocked))throw new Error();unlocked=[...new Set([...unlocked,...data.unlocked.filter(id=>ENDINGS.some(e=>e.id===id))])];legacy=[...new Set([...legacy,...(Array.isArray(data.legacy)?data.legacy:[]).filter(id=>LEGACY_ENDINGS.some(e=>e.id===id))])];const imported=readAchievementRecords(data.achievements,'imported');for(const [id,row]of Object.entries(imported)){if(!Object.hasOwn(achievements,id))achievements[id]={...row,source:'imported'};}save();toast('圖鑑與成就已匯入此瀏覽器。');}catch{toast('這不是可辨識的移動人生圖鑑檔案。');}event.target.value='';});
collectAchievements(false);save();home(false);void syncCloud();
